with c as (select id from public.academy_courses where id='meteorology-forecasting-foundations'),
ch as (insert into public.academy_chapters(course_id,title,description,sort_order,published) select id,'الظواهر الجوية الشديدة والمخاطر والإنذار المبكر','العواصف الرعدية والبرد والرياح الشديدة والسيول والغبار والحر الشديد والإنذار القائم على التأثير.',15,false from c on conflict(course_id,title) do update set description=excluded.description returning id),
u1 as (insert into public.academy_units(chapter_id,title,sort_order,published) select id,'العواصف الرعدية والظواهر المصاحبة',1,false from ch on conflict(chapter_id,title) do update set sort_order=excluded.sort_order returning id),
u2 as (insert into public.academy_units(chapter_id,title,sort_order,published) select id,'الهطول الشديد والسيول والفيضانات',2,false from ch on conflict(chapter_id,title) do update set sort_order=excluded.sort_order returning id),
u3 as (insert into public.academy_units(chapter_id,title,sort_order,published) select id,'الظواهر الجوية الإقليمية',3,false from ch on conflict(chapter_id,title) do update set sort_order=excluded.sort_order returning id),
u4 as (insert into public.academy_units(chapter_id,title,sort_order,published) select id,'الإنذار المبكر والتواصل',4,false from ch on conflict(chapter_id,title) do update set sort_order=excluded.sort_order returning id),
d(slug,title,summary,content,ord,mins,objectives,unit) as (values ('thunderstorm-electrical-activity','العواصف الرعدية والبرق والنشاط الكهربائي','بيئة العواصف الرعدية وتطور الشحنات الكهربائية ومؤشرات الرصد.','{"blocks":[{"type":"text","text":"تتكون العواصف الرعدية غالباً ضمن سحب ركامية مزنية عميقة تدعمها رطوبة وعدم استقرار ورفع مناسب."},{"type":"text","text":"تساعد التيارات الصاعدة والهابطة على فصل الشحنات الكهربائية داخل السحابة."},{"type":"text","text":"ينشأ البرق من تفريغ كهربائي بين مناطق مختلفة الشحنة داخل السحابة أو بين السحابة والسطح."},{"type":"text","text":"يحدث الرعد نتيجة التسخين السريع للهواء على طول قناة التفريغ وتمدد الهواء، ويصل الصوت بعد الضوء بسبب اختلاف سرعة الانتشار."},{"type":"text","text":"تختلف كثافة البرق ومواقع التفريغ خلال دورة حياة العاصفة، وقد تشير الزيادة المفاجئة إلى تغير النشاط داخلها."},{"type":"text","text":"تستخدم شبكات تحديد البرق لتقدير مواقع التفريغات وتوقيتها ونوعها وفق قدرات النظام."},{"type":"text","text":"يعرض الرادار بنية الهطول والانعكاسية ومؤشرات الدوران أو البرد المحتملة، لكنه لا يقيس البرق مباشرة."},{"type":"text","text":"تساعد الأقمار الصناعية في تتبع نمو قمم السحب الباردة ومعدل تطورها."},{"type":"text","text":"قد يحدث البرق خارج منطقة المطر الأشد أو بعد تراجع الهطول، لذلك لا يقتصر تقييم النشاط الكهربائي على صدى المطر."},{"type":"text","text":"تدمج بيانات البرق والرادار والأقمار والسبر لتقدير تطور العاصفة ومجال تأثيرها."},{"type":"text","text":"مثال: ارتفاع معدل البرق مع نمو سريع لقمم السحب قد يدعم تشخيص اشتداد الحمل، ويجب تأكيده بمصادر أخرى."},{"type":"callout","text":"خلاصة: تحليل العواصف الرعدية متعدد المصادر ويجمع الديناميكية والميكروفيزياء والرصد الكهربائي."}]}',760,55,'["شرح بيئة العواصف الرعدية","فهم آليات الشحن الكهربائي","قراءة بيانات البرق والرادار"]','العواصف الرعدية والظواهر المصاحبة'),
('hailstorms-and-ice-growth','البَرَد وآليات نمو الجليد داخل السحب','بيئة البرد وتراكم الجليد ومساراته داخل السحب الركامية.','{"blocks":[{"type":"text","text":"البَرَد هطول من كتل جليدية تتكون داخل سحب ركامية مزنية قوية."},{"type":"text","text":"يساعد وجود ماء سائل فائق التبريد وتيارات صاعدة كافية على نمو حبات البرد."},{"type":"text","text":"تلتقط نواة جليدية قطرات فائقة التبريد تتجمد على سطحها، ثم قد تكرر المرور في مناطق غنية بالماء السائل."},{"type":"text","text":"يعتمد حجم البرد على زمن النمو وكمية الماء المتاحة ومسار الحبة وشدة التيار الصاعد."},{"type":"text","text":"تؤثر بنية السحابة وارتفاع مستوى التجمد ومستوى الصفر الرطب في احتمالية وصول البرد إلى السطح دون ذوبان كامل."},{"type":"text","text":"قد يحمل التيار الصاعد القوي حبات الجليد إلى طبقات أعلى ثم تسقط عندما تتغلب الجاذبية على قوة الرفع."},{"type":"text","text":"تظهر بعض العواصف إشارات رادارية مرتبطة بوجود جليد أو انعكاسية مرتفعة، لكن تفسيرها يحتاج سياقاً ومقارنة بمنتجات أخرى."},{"type":"text","text":"تستخدم منتجات مثل الارتفاع الأقصى للانعكاسية ومؤشرات البرد المستنتجة لدعم التقييم، وليست قياساً مباشراً لحجم الحبة عند السطح."},{"type":"text","text":"تتأثر احتمالية وصول البرد بحالة الطبقات الدافئة أسفل السحابة ومدة سقوط الحبات خلالها."},{"type":"text","text":"تساعد تقارير الرصد الأرضية والتحقق اللاحق على تقييم أداء منتجات البرد."},{"type":"text","text":"مثال: انعكاسية قوية مع بيئة حملية شديدة ترفع الاهتمام بالبرد، لكن لا تكفي وحدها لتحديد حجمه أو أثره."},{"type":"callout","text":"خلاصة: توقع البرد يجمع بيئة الحمل ونمو الجليد والملف الحراري ومنتجات الرادار."}]}',770,55,'["شرح نمو حبات البرد","تحديد بيئة السحب الملائمة","فهم مؤشرات البرد في الرادار"]','العواصف الرعدية والظواهر المصاحبة'),
('severe-winds-downbursts','الرياح الشديدة والهبّات الهابطة','الهبّات الهابطة والاندفاعات الباردة والرياح المرتبطة بالعواصف.','{"blocks":[{"type":"text","text":"قد تنتج الرياح الشديدة عن تدرج ضغط واسع النطاق أو جبهة أو عاصفة حملية أو تأثير تضاريسي."},{"type":"text","text":"الهبّة الهابطة تيار هوائي هابط قوي ينتشر أفقياً عند وصوله إلى السطح."},{"type":"text","text":"قد تتشكل الاندفاعات الهابطة بسبب تبخر الهطول أو انصهار الجليد أو سحب الهواء الجاف إلى داخل التيار الهابط."},{"type":"text","text":"تتميز بعض الاندفاعات الهابطة بنطاق تأثير محدود نسبياً، بينما تمتد أخرى على مساحة أوسع."},{"type":"text","text":"قد يرافق التيار الهابط انخفاض في الحرارة وارتفاع نسبي في الضغط وتغير مفاجئ في اتجاه الرياح عند السطح."},{"type":"text","text":"تظهر جبهة الهبّات كحد فاصل بين هواء أبرد مندفع وهواء محيط، وقد تحفز خلايا حملية جديدة."},{"type":"text","text":"يساعد الرادار دوبلر في كشف أنماط الحركة الشعاعية المرتبطة بالتقارب والتباعد، مع مراعاة هندسة الشعاع وبعد الهدف."},{"type":"text","text":"تستخدم المحطات السطحية لتوثيق سرعة الرياح القصوى وتغير الضغط والحرارة والتوقيت."},{"type":"text","text":"قد تتسبب التضاريس والمباني في تغيرات محلية لا تمثلها شبكة النموذج أو الرصد الواسعة."},{"type":"text","text":"ينبغي التمييز بين سرعة الرياح المستمرة والهبة القصوى وفق تعريف القياس والفترة الزمنية."},{"type":"text","text":"مثال: تزامن قفزة الضغط وهبوط الحرارة وتغير الرياح مع إشارة رادارية مناسبة قد يدعم تشخيص مرور جبهة هبات."},{"type":"callout","text":"خلاصة: تحليل الرياح الشديدة يتطلب دمج الرصد السطحي والرادار وبنية العاصفة والبيئة المحيطة."}]}',780,55,'["تمييز أنواع الرياح الهابطة","فهم التبريد التبخري والاندفاع","قراءة مؤشرات الرياح الشديدة"]','العواصف الرعدية والظواهر المصاحبة'),
('tornadoes-and-rotating-storms','الأعاصير القمعية والعواصف الدوارة','الدوران داخل العواصف الرعدية والظروف البيئية المرتبطة بالأعاصير القمعية.','{"blocks":[{"type":"text","text":"الإعصار القمعي عمود هوائي دوار متصل بقاعدة سحابة ركامية مزنية وقد يمتد تأثيره إلى السطح."},{"type":"text","text":"تتطلب العواصف الدوارة المنظمة تفاعلاً بين عدم الاستقرار والقص الرأسي والرفع وبنية التيار الصاعد."},{"type":"text","text":"يساعد القص الاتجاهي والسرعي في تنظيم الدوران الأفقي الذي قد يميل داخل التيار الصاعد إلى دوران رأسي."},{"type":"text","text":"قد تحتوي بعض العواصف فائقة الخلية على دوران متوسط المقياس يسمى mesocyclone، ولا يعني وجوده بالضرورة تشكل إعصار قمعي."},{"type":"text","text":"تستخدم بيانات الرادار دوبلر لتحديد أنماط السرعة المتقابلة التي قد تشير إلى دوران داخل العاصفة."},{"type":"text","text":"تساعد بيانات السبر في تقييم CAPE والقص الرأسي ومستوى التكاثف والبيئة الحرارية والرطوبية."},{"type":"text","text":"تختلف الأعاصير القمعية في الشدة والمدة والمسار، ولا يمكن استنتاج الشدة من مظهر السحابة وحده."},{"type":"text","text":"قد تتشكل دوامات محلية أخرى قرب جبهات الهبات أو الحدود السطحية، ويجب تمييزها عن الأعاصير القمعية."},{"type":"text","text":"تتطلب عملية التشخيص توافقاً بين المشاهدات الرادارية والبصرية والتقارير الموثقة والبيئة الجوية."},{"type":"text","text":"تحد دقة الرادار وبعده عن العاصفة وتضاريس المنطقة من قدرة الكشف عن الدوران القريب من السطح."},{"type":"text","text":"مثال: ظهور زوج سرعة متقابلة في الرادار يستدعي فحص الاستمرارية الرأسية والتطور الزمني وبيانات العاصفة الأخرى."},{"type":"callout","text":"خلاصة: تشخيص العواصف الدوارة عملية متعددة الأدلة، ولا يكفي مؤشر منفرد لإثبات الإعصار."}]}',790,55,'["شرح الدوران داخل العواصف","التعرف إلى مؤشرات السبر والرادار","تمييز الإعصار القمعي عن الدوامات الأخرى"]','العواصف الرعدية والظواهر المصاحبة'),
('heavy-rain-flash-flood-meteorology','الأمطار الغزيرة والسيول المفاجئة: العوامل الجوية','الرفع والرطوبة ومعدل الهطول والتجدد الخلوي وعلاقتها بالسيول.','{"blocks":[{"type":"text","text":"تنتج الأمطار الغزيرة من اجتماع الرطوبة والرفع والاستقرار الملائم ومدة استمرار الهطول فوق المنطقة."},{"type":"text","text":"قد تتسبب حركة بطيئة للنظام أو تجدد الخلايا على المسار نفسه في تراكمات مرتفعة."},{"type":"text","text":"يعرف التدريب الخلوي training بأنه مرور خلايا متتابعة فوق نطاق مكاني متقارب، ما يرفع التراكم المحلي."},{"type":"text","text":"تؤثر التضاريس في رفع الهواء الرطب وتوجيه الهطول، وقد تتغير الكميات بشدة على مسافات قصيرة."},{"type":"text","text":"تختلف الاستجابة الهيدرولوجية بحسب رطوبة التربة السابقة والانحدار ونفاذية السطح وشكل الحوض."},{"type":"text","text":"قد تحدث السيول المفاجئة حتى مع مساحات هطول محدودة إذا كانت شدة المطر كبيرة وزمن الاستجابة قصيراً."},{"type":"text","text":"تساعد خرائط الهطول التراكمي والرادار والمحطات في تقدير مكان وشدة المطر، مع فحص جودة كل مصدر."},{"type":"text","text":"تستخدم نماذج التنبؤ الهيدرولوجي بيانات المطر والتربة والتدفق لتقدير الاستجابة المائية."},{"type":"text","text":"ينبغي التمييز بين التنبؤ بالهطول والتنبؤ بالفيضان؛ فلكل منهما مصادر عدم يقين مختلفة."},{"type":"text","text":"تؤثر السدود وشبكات التصريف والتحضر وتغير استخدام الأرض في مسار المياه والاستجابة المحلية."},{"type":"text","text":"مثال: قد ينتج خطر سيول مرتفع عن مطر متوسط الشدة لكنه مستمر فوق حوض مشبع صغير."},{"type":"callout","text":"خلاصة: تقييم السيول يحتاج دمج الأرصاد والهيدرولوجيا وخصائص الحوض والتعرض."}]}',800,55,'["تحليل أسباب المطر الغزير","فهم التجدد الخلوي والتراكم","ربط الهطول باستجابة الحوض"]','الهطول الشديد والسيول والفيضانات'),
('coastal-storms-and-sea-state','العواصف الساحلية وحالة البحر','الرياح والضغط والأمواج وارتفاع مستوى البحر والتأثيرات الساحلية.','{"blocks":[{"type":"text","text":"تتأثر حالة البحر بسرعة الرياح ومدتها ومسافة تأثيرها فوق سطح الماء fetch."},{"type":"text","text":"تنتقل الطاقة من الرياح إلى سطح البحر فتتولد أمواج تختلف في ارتفاعها وفترتها واتجاهها."},{"type":"text","text":"يتأثر ارتفاع الموج بمدة هبوب الرياح والمسافة المفتوحة وعمق المياه والتضاريس الساحلية."},{"type":"text","text":"قد يؤدي انخفاض الضغط واندفاع الرياح نحو الساحل إلى ارتفاع غير اعتيادي في مستوى البحر يسمى المد العاصفي."},{"type":"text","text":"يختلف المد العاصفي عن المد الفلكي الناتج عن تأثير جاذبية القمر والشمس، وقد يتزامنان فيزيد مستوى المياه الكلي."},{"type":"text","text":"يسهم شكل الساحل وعمق الجرف القاري واتجاه الخليج في تضخيم أو تخفيف أثر الأمواج وارتفاع المياه."},{"type":"text","text":"تستخدم العوامات البحرية ومقاييس المد والأقمار والنماذج البحرية لرصد حالة البحر."},{"type":"text","text":"تؤثر العواصف خارج المدارية والمنخفضات المدارية في الرياح والضغط والأمواج وفق مسارها وشدتها."},{"type":"text","text":"قد تتسبب الأمواج الطويلة القادمة من عاصفة بعيدة في اضطراب الساحل حتى بعد هدوء الرياح محلياً."},{"type":"text","text":"يتطلب التوقع الساحلي دمج الطقس البحري والمد الفلكي وشكل الساحل ومستوى البحر الأساسي."},{"type":"text","text":"مثال: تزامن مد فلكي مرتفع مع مد عاصفي وأمواج قوية قد يزيد احتمال تجاوز المياه للحواجز الساحلية."},{"type":"callout","text":"خلاصة: المخاطر الساحلية تنتج من تفاعل الغلاف الجوي والمحيط والهندسة الساحلية."}]}',810,55,'["فهم تولد الأمواج بفعل الرياح","تمييز المد العاصفي عن المد الفلكي","تحليل ظروف العواصف الساحلية"]','الهطول الشديد والسيول والفيضانات'),
('dust-storms-and-aerosol-transport','العواصف الغبارية ونقل الهباء الجوي','مصادر الغبار والرفع والنقل والترسيب والرصد بالأقمار والمحطات.','{"blocks":[{"type":"text","text":"يتكون الغبار الجوي من جسيمات معدنية دقيقة ترفعها الرياح من أسطح جافة ومفككة التربة."},{"type":"text","text":"تسهم سرعة الرياح وقابلية السطح للتعرية والرطوبة والغطاء النباتي في تحديد قابلية إثارة الغبار."},{"type":"text","text":"قد تبدأ العواصف الغبارية من جبهات هبات العواصف الرعدية أو الرياح القوية المرتبطة بالمنخفضات."},{"type":"text","text":"ينقل الغبار أفقياً لمسافات متفاوتة وفق حجم الجسيمات وارتفاع الخلط والرياح الرأسية والأفقية."},{"type":"text","text":"تترسب الجسيمات بفعل الجاذبية والترسيب الرطب عندما تلتقطها قطرات السحب أو الهطول."},{"type":"text","text":"تؤثر خصائص الهباء في الإشعاع والرؤية وتفاعلات السحب، ويختلف الأثر بحسب التركيب والحجم والتركيز."},{"type":"text","text":"تستخدم الأقمار الصناعية منتجات عمق الكثافة البصرية للهباء ومؤشرات الغبار لتتبع الامتداد، مع مراعاة صعوبة التمييز فوق بعض الأسطح."},{"type":"text","text":"تقيس محطات جودة الهواء تركيز الجسيمات مثل PM10 وPM2.5 وفق مواقعها وطرق القياس."},{"type":"text","text":"قد تحد السحب أو الأسطح الساطعة أو الغطاء الأرضي من دقة بعض منتجات الاستشعار الفضائي."},{"type":"text","text":"تحتاج توقعات الغبار إلى ربط سرعة الرياح ورطوبة التربة ومصادر الغبار ومسارات النقل."},{"type":"text","text":"مثال: مرور جبهة باردة فوق أرض جافة قد يثير الغبار، لكن شدة الحدث تعتمد على الرياح وخصائص السطح ومصدر الجسيمات."},{"type":"callout","text":"خلاصة: الغبار ظاهرة جوية-سطحية تتطلب بيانات الأرصاد والاستشعار عن بعد وجودة الهواء."}]}',820,55,'["شرح آليات إثارة الغبار","فهم النقل والترسيب","قراءة منتجات الغبار"]','الظواهر الجوية الإقليمية'),
('heat-health-weather-risk','الحرارة الشديدة ومؤشرات الإجهاد الحراري','العلاقة بين الحرارة والرطوبة والرياح والإشعاع ومؤشرات الإحساس الحراري.','{"blocks":[{"type":"text","text":"لا تعكس درجة حرارة الهواء وحدها العبء الحراري على الإنسان؛ إذ تؤثر الرطوبة والرياح والإشعاع والظل والنشاط البدني."},{"type":"text","text":"تقلل الرطوبة العالية قدرة تبخر العرق على تبريد الجسم، ما قد يرفع الإجهاد الحراري."},{"type":"text","text":"تزيد الرياح التبريد التبخري في ظروف كثيرة، لكن أثرها يعتمد على الحرارة والرطوبة ودرجة تعرض الجسم."},{"type":"text","text":"تؤثر أشعة الشمس المباشرة والإشعاع الحراري من الأسطح في الحمل الحراري على الجسم."},{"type":"text","text":"تستخدم مؤشرات مثل الحرارة الظاهرية أو مؤشر الحرارة لتمثيل بعض جوانب الإجهاد، ولكل مؤشر افتراضات وحدود."},{"type":"text","text":"تختلف المؤشرات المستخدمة بحسب ما إذا كانت مصممة للظل أو الشمس المباشرة أو بيئة العمل الخارجية."},{"type":"text","text":"تتغير قابلية التأثر بالحرارة بين الأشخاص والبيئات، وتتطلب الرسائل الصحية الرجوع إلى الإرشادات الرسمية المحلية."},{"type":"text","text":"تساعد التوقعات متعددة الأيام في تحديد فترات استمرار الحرارة وعدم وجود تبريد ليلي كافٍ."},{"type":"text","text":"تؤثر المدن والمواد العمرانية وقلة الظل في الجزر الحرارية الحضرية ودرجات الحرارة المحلية."},{"type":"text","text":"ينبغي عدم مساواة مؤشر واحد بتقييم طبي؛ فالمنتجات الجوية تقدم تقديراً بيئياً عاماً."},{"type":"text","text":"مثال: حرارة معتدلة نسبياً مع رطوبة مرتفعة وشمس قوية قد تعطي إجهاداً أكبر من الحرارة وحدها."},{"type":"callout","text":"خلاصة: توقع مخاطر الحر يجمع عناصر الطقس وخصائص البيئة والتواصل الصحي المسؤول."}]}',830,55,'["تمييز حرارة الهواء عن الإجهاد الحراري","فهم مؤشرات الحرارة الظاهرية","ربط التوقع بالمخاطر الصحية"]','الظواهر الجوية الإقليمية'),
('impact-based-warning-framework','التحذير القائم على التأثير وتقدير المخاطر','دمج الاحتمال والشدة والتعرض والهشاشة لصياغة تحذيرات مفيدة.','{"blocks":[{"type":"text","text":"الخطر ظاهرة قد تسبب ضرراً، بينما يعبر الخطر المتوقع أو المخاطر عن تفاعل احتمال الحدث وشدته مع التعرض والهشاشة."},{"type":"text","text":"يتطلب التحذير القائم على التأثير تجاوز وصف الظاهرة إلى بيان الآثار المحتملة على الناس والبنية التحتية والخدمات."},{"type":"text","text":"تحدد شدة الظاهرة عبر مقاييس مناسبة مثل كمية المطر أو سرعة الرياح أو مدة الحر، وفق السياق المحلي."},{"type":"text","text":"يشير التعرض إلى وجود السكان أو الأصول أو الخدمات في نطاق الظاهرة المتوقعة."},{"type":"text","text":"تعبر الهشاشة عن مدى قابلية العناصر المعرضة للتأثر، وتتغير بحسب البنية والجاهزية والظروف الاجتماعية."},{"type":"text","text":"تؤثر القدرة على الاستجابة والإنذار والإخلاء والتواصل في مستوى الخطر المتبقي."},{"type":"text","text":"تحتاج مصفوفات المخاطر إلى تعريفات واضحة للاحتمال والشدة وفئات التأثير حتى تكون متسقة."},{"type":"text","text":"يجب ربط كل رسالة تحذير بمنطقة وفترة زمنية وظاهرة وتأثير محتمل وإجراء رسمي موثوق."},{"type":"text","text":"تستخدم خرائط التعرض والبيانات السكانية والبنية التحتية لتحسين التقدير المكاني، مع حماية الخصوصية وجودة البيانات."},{"type":"text","text":"تراجع التحذيرات بعد الحدث بمقارنة التوقعات والآثار المرصودة لتطوير العتبات والإجراءات."},{"type":"text","text":"مثال: كمية مطر واحدة قد تسبب أثراً مختلفاً في مدينة كثيفة العمران مقارنة بمنطقة ذات تصريف طبيعي جيد."},{"type":"callout","text":"خلاصة: التحذير الفعال يربط الطقس بالأثر المتوقع ويشرح عدم اليقين ويحدد الرسالة العملية."}]}',840,55,'["تمييز الخطر عن المخاطر","تحديد التعرض والهشاشة","صياغة تحذير قائم على التأثير"]','الإنذار المبكر والتواصل'),
('multi-hazard-early-warning-systems','أنظمة الإنذار المبكر متعددة المخاطر','مكونات الرصد والتنبؤ ونشر التحذير والاستعداد والتقييم اللاحق.','{"blocks":[{"type":"text","text":"يتكون نظام الإنذار المبكر من معرفة المخاطر والرصد والتحليل والتنبؤ ونشر التحذيرات والاستعداد للاستجابة."},{"type":"text","text":"تحتاج معرفة المخاطر إلى خرائط التعرض والسجلات التاريخية وتحليل التغيرات البيئية والمناخية."},{"type":"text","text":"تجمع شبكات الرصد بيانات المحطات والرادار والأقمار والقياسات البحرية والهيدرولوجية."},{"type":"text","text":"تدمج مراكز التنبؤ البيانات في تحليلات وتوقعات قابلة للتحديث، وتحدد عتبات الإنذار وفق الخطر المحلي."},{"type":"text","text":"يجب أن تصل الرسالة في وقت مناسب وبصياغة مفهومة ومن خلال قنوات متعددة وموثوقة."},{"type":"text","text":"تتطلب الاستجابة أدواراً واضحة بين الأرصاد والدفاع المدني والبلديات والصحة والمياه والإعلام."},{"type":"text","text":"قد تتسلسل المخاطر؛ فالأمطار الغزيرة قد تؤدي إلى فيضانات وانهيارات أرضية وتعطل خدمات."},{"type":"text","text":"يحتاج الإنذار متعدد المخاطر إلى تنسيق الرسائل حتى لا تتعارض التحذيرات أو تتكرر بصورة تربك الجمهور."},{"type":"text","text":"تُختبر الأنظمة بتمارين دورية ومراجعة زمن وصول البيانات وإصدار التحذير واستجابة الجهات."},{"type":"text","text":"تقاس الفعالية ليس فقط بدقة التنبؤ، بل أيضاً بوصول الرسالة وفهمها واتخاذ الإجراء المناسب."},{"type":"text","text":"مثال: تحذير مطري فعال يتطلب ربط توقع المطر بحالة الأحواض والتصريف والطرق وقنوات الإبلاغ المحلية."},{"type":"callout","text":"خلاصة: الإنذار المبكر منظومة مؤسسية متكاملة تبدأ بالبيانات وتنتهي بالاستعداد والاستجابة والتعلم."}]}',850,55,'["تحديد مكونات الإنذار المبكر","فهم تعدد المخاطر وترابطها","تقييم وصول التحذير وفعاليته"]','الإنذار المبكر والتواصل'))
insert into public.academy_lessons(course_id,chapter_id,unit_id,slug,title,summary,content,published,sort_order,level,estimated_minutes,learning_objectives,chapter_title,unit_title)
select c.id,ch.id,case d.unit when 'العواصف الرعدية والظواهر المصاحبة' then u1.id when 'الهطول الشديد والسيول والفيضانات' then u2.id when 'الظواهر الجوية الإقليمية' then u3.id when 'الإنذار المبكر والتواصل' then u4.id end,d.slug,d.title,d.summary,d.content::jsonb,false,d.ord,'advanced',d.mins,d.objectives::jsonb,'الظواهر الجوية الشديدة والمخاطر والإنذار المبكر',d.unit from d cross join c cross join ch cross join u1 cross join u2 cross join u3 cross join u4
on conflict(course_id,slug) do update set chapter_id=excluded.chapter_id,unit_id=excluded.unit_id,title=excluded.title,summary=excluded.summary,content=excluded.content,published=false,sort_order=excluded.sort_order,level=excluded.level,estimated_minutes=excluded.estimated_minutes,learning_objectives=excluded.learning_objectives,chapter_title=excluded.chapter_title,unit_title=excluded.unit_title;